import{_ as a,c as n,o as t,ah as i}from"./chunks/framework.DaDXF32t.js";const u=JSON.parse('{"title":"UV Acceptance and Banner Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-08-02-uv-acceptance-and-banner-design.md","filePath":"superpowers/specs/2026-08-02-uv-acceptance-and-banner-design.md","lastUpdated":1785749755000}'),s={name:"superpowers/specs/2026-08-02-uv-acceptance-and-banner-design.md"};function r(l,e,o,c,d,p){return t(),n("div",null,e[0]||(e[0]=[i(`<h1 id="uv-acceptance-and-banner-design" tabindex="-1">UV Acceptance and Banner Design <a class="header-anchor" href="#uv-acceptance-and-banner-design" aria-label="Permalink to “UV Acceptance and Banner Design”">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to “Goal”">​</a></h2><p>Stop valid portable UV packages from being rejected and repeatedly downloaded, and replace the installer header with the approved compact BAAS banner centered in the terminal.</p><h2 id="uv-acceptance" tabindex="-1">UV acceptance <a class="header-anchor" href="#uv-acceptance" aria-label="Permalink to “UV acceptance”">​</a></h2><p>The installer will not calculate, download, pin, or compare a SHA-256 digest for the portable UV archive. The configured mirror assets are mutable, so a digest copied from one UV release cannot establish whether a differently versioned mirror asset is usable.</p><p>For each source in measured order, the installer will:</p><ol><li>download the archive into the installation root&#39;s temporary directory;</li><li>extract it into the installation root&#39;s UV toolkit directory;</li><li>locate and install the platform UV executable;</li><li>run that exact executable with <code>--version</code> through the existing PTY process path;</li><li>accept the source immediately when the command exits successfully.</li></ol><p>Download, extraction, executable discovery, or execution failure causes cleanup of that attempted UV installation before the next source is tried. A successful executable check stops source iteration, preventing another full archive download. Existing dependency-state SHA caching remains unchanged because it controls whether dependency resolution is needed; only UV archive verification is removed.</p><h2 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to “Header”">​</a></h2><p>The installer will display this exact six-line banner:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>██████╗  █████╗  █████╗ ███████╗</span></span>
<span class="line"><span>██╔══██╗██╔══██╗██╔══██╗██╔════╝</span></span>
<span class="line"><span>██████╔╝███████║███████║███████╗</span></span>
<span class="line"><span>██╔══██╗██╔══██║██╔══██║╚════██║</span></span>
<span class="line"><span>██████╔╝██║  ██║██║  ██║███████║</span></span>
<span class="line"><span>╚═════╝ ╚═╝  ╚═╝╚═╝  ╚═╝╚══════╝</span></span></code></pre></div><p>Each banner row and each metadata row will be centered independently by FTXUI using terminal display columns. No manual byte-length or common-width padding will be used. This keeps UTF-8 box-drawing characters aligned and preserves centering when the viewport width changes.</p><h2 id="error-handling-and-observability" tabindex="-1">Error handling and observability <a class="header-anchor" href="#error-handling-and-observability" aria-label="Permalink to “Error handling and observability”">​</a></h2><p>UV source failures remain visible in the unified installer log. The installer will distinguish download, extraction, executable discovery, and <code>uv --version</code> failures. It will not emit a SHA verification error. All UV subprocess output continues to arrive through PTY chunks.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to “Verification”">​</a></h2><p>Automated regression tests will first demonstrate the current failures and then verify:</p><ul><li>a downloaded archive is accepted without a matching pinned digest when its extracted UV executable passes <code>--version</code>;</li><li>an unusable extracted executable causes the next source to be attempted;</li><li>the old and new banner rows cannot be confused, and all six approved rows render;</li><li>independently centered Unicode rows share the viewport center.</li></ul><p>After the automated suite and release build pass, a complete install will run in a new disposable directory. The smoke test must show one successful UV archive download, a successful local <code>uv --version</code>, dependency installation, OCR placement, and BAAS launch. The disposable directory will be removed after confirmation under the applicable deletion policy.</p>`,18)]))}const b=a(s,[["render",r]]);export{u as __pageData,b as default};
